SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;
-- usr_lesson DDL
CREATE TABLE `usr_lesson` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT Comment "id[input]",
`lesson_name` VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL Comment "课程[input]",
`student_id` INT UNSIGNED NULL Comment "学生id[input]",
`student_name` VARCHAR(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "学生名称[input]",
INDEX `student_id`(`student_id` ASC) USING BTREE,
INDEX `student_name`(`student_name` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci AUTO_INCREMENT = 7 ROW_FORMAT = Dynamic COMMENT = "学生课程";
-- usr_preview DDL
CREATE TABLE `usr_preview` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT Comment "id[input]",
`create_time` INT UNSIGNED NOT NULL DEFAULT 0 Comment "创建时间[date|Y-m-d H:i:s]",
`update_time` INT UNSIGNED NOT NULL DEFAULT 0 Comment "修改时间[date|Y-m-d H:i:s]",
`create_user` TINYINT UNSIGNED NOT NULL DEFAULT 0 Comment "创建用户[input]",
`update_user` TINYINT UNSIGNED NOT NULL DEFAULT 0 Comment "修改用户[input]",
`lead_time` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' Comment "提前时间[input]",
`switch` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' Comment "发送状态[radio|1=已发送&2=未发送]",
`image` TEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "图片[file]",
`belong_student_id` INT UNSIGNED NOT NULL Comment "所属学生[input]",
`belong_curriculum_id` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' Comment "所属课程[input]",
`template_message` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' Comment "模板消息[json]",
`remind_type` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' Comment "提醒类型[radio|1=已发送&2=未发送]",
`specific_time` VARCHAR(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' Comment "特定时间[input]",
INDEX `belong_student_id`(`belong_student_id` ASC) USING BTREE,
PRIMARY KEY (`id`,
`belong_student_id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 474 ROW_FORMAT = Dynamic;
-- usr_school DDL
CREATE TABLE `usr_school` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT Comment "id[input]",
`create_time` INT UNSIGNED NOT NULL DEFAULT 0 Comment "时间[date|Y-m-d H:i:s]",
`student_name` VARCHAR(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "姓名[input]",
`student_gender` TINYINT NOT NULL Comment "性别[radio|1=男&2=女]",
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 124 ROW_FORMAT = Dynamic;
-- usr_student DDL
CREATE TABLE `usr_student` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT Comment "id[input]",
`create_time` INT UNSIGNED NOT NULL DEFAULT 0 Comment "时间[date|Y-m-d H:i:s]",
`student_name` VARCHAR(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "姓名[input]",
`student_gender` TINYINT NOT NULL Comment "性别[radio|1=男&2=女&3=保密]",
`student_like` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "爱好[checkbox|1=看书&2=旅游&3=音乐]",
`student_img` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "头像[file]",
`student_json` JSON NOT NULL Comment "配置[json]",
`student_html` TEXT CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "富文本[editor]",
`student_float` FLOAT NOT NULL Comment "浮点型[float]",
`student_select` TINYINT NOT NULL Comment "下拉框[select|1=男&2=女]",
`student_notice` VARCHAR(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "通知[checkbox|1=全校&2=班级&3=个人]",
`student_file` VARCHAR(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL Comment "文件[file]",
`student_fee` TINYINT NOT NULL Comment "学费[radio|1=已交&2=未交&3=未知]",
INDEX `id`(`id` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci AUTO_INCREMENT = 244 ROW_FORMAT = Dynamic COMMENT = "学生列表";
-- usr_student_class DDL
CREATE TABLE `usr_student_class` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT Comment "id[input]",
`class_name` VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL Comment "班级[input]",
`student_id` INT UNSIGNED NOT NULL Comment "学生id[input]",
INDEX `class_student_id`(`student_id` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci AUTO_INCREMENT = 86 ROW_FORMAT = Dynamic;
-- usr_lesson Indexes
ALTER TABLE `usr_lesson` 
 ADD CONSTRAINT `student_id` FOREIGN KEY (`student_id`) REFERENCES `usr_student` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION;
-- usr_preview Indexes
ALTER TABLE `usr_preview` 
 ADD CONSTRAINT `belong_student_id` FOREIGN KEY (`belong_student_id`) REFERENCES `usr_student` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION;
-- usr_student_class Indexes
ALTER TABLE `usr_student_class` 
 ADD CONSTRAINT `class_student_id` FOREIGN KEY (`student_id`) REFERENCES `usr_student` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION;
